export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const t = Math.max(0, Math.min(time, 2 * tTop));

  const y = u * t - 0.5 * g * t * t;
  const v = u - g * t;
  const a = -g;
  const Fg = m * g;

  let motionState = "Ready to toss";
  if (t > 0 && t < tTop - 0.05) motionState = "Rising";
  else if (Math.abs(t - tTop) <= 0.05) motionState = "At the top";
  else if (t > tTop + 0.05 && y > 0) motionState = "Falling";
  else if (y <= 0 && t > 0) motionState = "Back at launch height";

  const objects = [];
  objects.push(...sdk.panel({ x: 20, y: 30, w: 290, h: 330, title: "The Motion", state: motionState }));
  objects.push(sdk.axis("axis.y", { x: 60, y: 80, length: 240, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));

  const ballY = 320 - (y / 2.2) * 240;
  objects.push(sdk.circle("ball.toss", 160, ballY, 24, { role: "output" }));

  objects.push(...sdk.vector("vec.v", { x: 190, y: ballY }, { value: v, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a", { x: 220, y: ballY }, { value: a, direction: "up" }, { scale: 15, label: "a" }));

  objects.push(...sdk.callout(240, ballY - 20, [
    `v: ${v.toFixed(2)} m/s`,
    `a: ${a.toFixed(2)} m/s^2`,
    `Fg: ${Fg.toFixed(1)} N`
  ], { id: "callout.toss" }));

  const pts = [];
  const steps = 20;
  const maxT = 2 * tTop;
  for (let i = 0; i <= steps; i++) {
    const st = (i / steps) * maxT;
    const sv = u - g * st;
    const px = 350 + (st / 1.8) * 260;
    const py = 240 - ((sv + 5.5) / 11) * 200;
    pts.push([px, py]);
  }

  objects.push(sdk.plot("plot.vt", {
    x: 340, y: 40, w: 280, h: 260,
    axes: {
      x: { label: "Time", min: 0, max: 1.8, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points: pts.slice(0, Math.floor((t / maxT) * steps) + 1) }
    ]
  }));

  objects.push(sdk.text("plot.vt.note", 350, 320, "Slope a = -g", { role: "neutral" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: Number(v.toFixed(2)) },
        { id: "acceleration", value: Number(a.toFixed(2)) },
        { id: "force", value: Number(Fg.toFixed(2)) },
        { id: "motionState", value: motionState }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: yTop,
      height: y,
      velocity: v,
      acceleration: a,
      force: Fg
    }
  };
}
